-- ts-analytics 1.0.0 – zobrazení stránek a události (MySQL / MariaDB)
CREATE TABLE IF NOT EXISTS ts_an_hits (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, ts INT UNSIGNED NOT NULL, day CHAR(10) NOT NULL, vid CHAR(16) NOT NULL, sid CHAR(16) NOT NULL, newv TINYINT NOT NULL DEFAULT 0, kind CHAR(2) NOT NULL, path VARCHAR(200) NOT NULL DEFAULT '', ref VARCHAR(100) NOT NULL DEFAULT '', src VARCHAR(60) NOT NULL DEFAULT '', med VARCHAR(60) NOT NULL DEFAULT '', camp VARCHAR(80) NOT NULL DEFAULT '', lang VARCHAR(8) NOT NULL DEFAULT '', dev CHAR(1) NOT NULL DEFAULT '', br VARCHAR(12) NOT NULL DEFAULT '', os VARCHAR(12) NOT NULL DEFAULT '', ev VARCHAR(40) NOT NULL DEFAULT '', KEY ts_an_hits_day (day), KEY ts_an_hits_sid (sid, ts)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_an_rate (bucket VARCHAR(120) NOT NULL PRIMARY KEY, window_start INT NOT NULL, count INT NOT NULL DEFAULT 0) DEFAULT CHARSET=utf8mb4;
